#!/usr/bin/python3
"""Writes Sources/Seshka/Icon.swift from the SVG drawings in design/."""
import os

here = os.path.dirname(os.path.abspath(__file__))


def svg(path):
    text = open(os.path.join(here, path)).read().strip()
    return "\n".join("    " + line for line in text.splitlines())


source = f'''import AppKit

/// The matryoshka logo for the menu bar (the color one is drawn live, see Matryoshka.swift). Generated by scripts/make-icon.sh from the SVGs in design/ - do not edit by hand.
enum Icon {{
    // One color, for the menu bar.
    private static let closedSVG = """
{svg("matryoshka-closed.svg")}
    """
    private static let openSVG = """
{svg("matryoshka-open.svg")}
    """

    private static func load(_ svg: String, size: CGFloat) -> NSImage {{
        let image = NSImage(data: Data(svg.utf8)) ?? NSImage()
        image.size = NSSize(width: size, height: size)
        return image
    }}

    /// Menu bar icon: open while leftover processes exist, closed otherwise.
    /// A template image, so the system colors it to match the menu bar.
    static func menuBar(open: Bool) -> NSImage {{
        let image = load(open ? openSVG : closedSVG, size: 18)
        image.isTemplate = true
        return image
    }}

    static let menuBarClosed = menuBar(open: false)
    static let menuBarOpen = menuBar(open: true)
}}
'''
with open(os.path.join(here, "..", "Sources", "Seshka", "Icon.swift"), "w") as f:
    f.write(source)
